"""Generated by solo-to-scale; edit `templates/tools/doctor.py` in the plugin, then run upgrade.

Is this venture's operating system set up and healthy? One list of what's done, what's missing and what's broken,
each with the fix and the handbook section. The `doctor` skill runs it; the dashboard shows it as the Setup card;
the session-start hook names how many items need you.

  python tools/doctor.py [--offline] [--json]   # report; exits 1 when something is broken
  python tools/doctor.py --repair [--offline]   # also fix what is safe to fix, then report again:
                                                #   adds missing founder-owned files to their gates' paths,
                                                #   writes an empty founder/goals.json, creates missing labels.
                                                #   File changes are left in the working tree for a PR.

Statuses: ok, todo (set it up when you're ready), broken (fix it: something will silently not happen), info
(optional, not set up) and unknown (couldn't be checked from here). Secrets are never read: the dashboard workflow
passes only whether each one is set (S2S_HAS_<NAME>=true/false); locally, the names come from the GitHub API.
Python 3 standard library plus the gh CLI for the GitHub checks; --offline checks the repo only.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402
import goals  # noqa: E402
import heartbeat  # noqa: E402
import tickets  # noqa: E402

# Founder-owned files and the gate that must cover each, so an agent can't change them without the founder.
GATED = {"founder/team.md": "hire", "founder/heartbeats.json": "budget", "founder/dashboard.json": "deploy",
         "founder/portfolio.json": "deploy", "founder/goals.json": "decision",
         "founder/finance.json": "spend"}
WORKFLOWS = ["governance.yml", "founder-gates.yml", "tickets.yml", "dashboard.yml", "portfolio.yml"]
LABELS = {tickets.TICKET: "0e8a16", tickets.CLAIMED: "fbca04", tickets.BLOCKED: "b60205", tickets.LOG: "c5def5",
          approval.LABEL: "d93f0b", approval.PR_LABEL: "0e8a16", heartbeat.COST_LOG: "c5def5",
          "agent-controls": "5319e7",
          **{f"role:{r}": "1d76db" for r in tickets.ROLES}}
NO_RUN_HOURS = 72
GOALS_TEMPLATE = {
    "about": "The company goal, this quarter's objectives and their key results. Only the founder edits this file "
             "(the decision gate). See the handbook, 'Goals and key results'.",
    "goal": "", "horizon": "", "objectives": []}
STATUSES = ("broken", "todo", "unknown", "info", "ok")


def item(key: str, title: str, status: str, detail: str = "", fix: str = "", section: str = "",
         repair: str = "") -> dict[str, str]:
    return {"key": key, "title": title, "status": status, "detail": detail, "fix": fix, "section": section,
            "repair": repair}


def load_json(root: Path, rel: str) -> Any:
    text = s.read(root / rel)
    if not text:
        return None
    try:
        return json.loads(text)
    except ValueError:
        return ValueError(f"{rel} is not valid JSON")


def has_secret(name: str, hub: tickets.Hub | None, cache: dict[str, Any]) -> bool | None:
    """True or False when we can tell whether a repository secret is set, None when we can't. Never its value."""
    flag = os.environ.get(f"S2S_HAS_{name}", "").strip().lower()
    if flag in ("true", "false"):
        return flag == "true"
    if hub is None:
        return None
    if "names" not in cache:
        try:
            got = hub.api("actions/secrets?per_page=100") or {}
            cache["names"] = {x.get("name") for x in got.get("secrets") or []}
        except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError, AttributeError):
            cache["names"] = None
    names = cache["names"]
    return None if names is None else name in names


def repo_checks(root: Path) -> list[dict[str, str]]:
    out = []
    proj = s.project(root)
    missing = [k for k in ("name", "repo", "one_line") if not str(proj.get(k) or "").strip()]
    out.append(item("project", "Project name, repo and one line", "broken" if missing else "ok",
                    f"founder/project.json is missing {', '.join(missing)}" if missing else proj.get("name", ""),
                    "Fill them in founder/project.json, then run upgrade", "Day 0 setup"))

    wf = root / ".github" / "workflows"
    gone = [w for w in WORKFLOWS if not (wf / w).exists()]
    out.append(item("workflows", "CI workflows", "broken" if gone else "ok",
                    "missing: " + ", ".join(gone) if gone else f"{len(WORKFLOWS)} workflows in place",
                    "Run the upgrade skill: it restores plugin-owned files", "CI/CD"))

    gates = load_json(root, "founder/gates.json")
    if not isinstance(gates, dict):
        out.append(item("gates", "Approval gates", "broken", "founder/gates.json is missing or not valid JSON",
                        "Run the upgrade skill, or restore the file from git history", "Decisions and traceability"))
    else:
        uncovered = [f"{rel} ({gate})" for rel, gate in GATED.items()
                     if rel not in ((gates.get("gates") or {}).get(gate) or {}).get("paths", [])]
        out.append(item("gates", "Founder-owned files behind their gates", "broken" if uncovered else "ok",
                        "not covered: " + ", ".join(uncovered) if uncovered else "every founder-owned file is gated",
                        "Add each file to its gate's paths in founder/gates.json (doctor --repair does it)",
                        "Decisions and traceability", "gates" if uncovered else ""))

    if not (root / "founder" / "goals.json").exists():
        out.append(item("goal", "Company goal", "todo", "founder/goals.json doesn't exist yet",
                        "doctor --repair writes an empty one; then set the goal", "Decisions and traceability", "goals"))
    else:
        g = goals.load(root)
        found = goals.problems(root, g)
        if found:
            out.append(item("goal", "Company goal", "broken", "; ".join(found[:3]),
                            "Fix founder/goals.json (python tools/goals.py check)", "Decisions and traceability"))
        else:
            out.append(item("goal", "Company goal", "ok" if str(g.get("goal") or "").strip() else "todo",
                            str(g.get("goal") or "not set"), "Write one measurable sentence as goal in founder/goals.json",
                            "Decisions and traceability"))
            live = goals.active(g)
            krs = sum(len(o.get("key_results") or []) for o in live)
            out.append(item("objectives", "This quarter's objectives", "ok" if live and krs else "todo",
                            f"{len(live)} active, {krs} key results" if live else "none active",
                            "Add 1 to 3 objectives with 2 to 4 key results each to founder/goals.json",
                            "Decisions and traceability"))

    pol = heartbeat.policy(root)
    roles = pol.get("roles") or {}
    on = [r for r, v in roles.items() if isinstance(v, dict) and v.get("enabled") and r != "board"]
    unfunded = [r for r in on if not (roles[r].get("monthly_budget_usd") or 0) > 0]
    if unfunded:
        out.append(item("budgets", "Heartbeats and budgets", "broken", "on without a budget: " + ", ".join(unfunded),
                        "Set monthly_budget_usd for each in founder/heartbeats.json (the budget gate)", "The AI team"))
    else:
        out.append(item("budgets", "Heartbeats and budgets", "ok" if on else "info",
                        f"on: {', '.join(on)}" if on else "no role wakes on its own yet",
                        "" if on else "When you're ready, turn a role on in founder/heartbeats.json and create its "
                        "scheduled task (python tools/heartbeat.py plan)", "The AI team"))
    return out


def hosting_checks(root: Path, hub: tickets.Hub | None, cache: dict[str, Any]) -> list[dict[str, str]]:
    import build_dashboard as bd  # imported late: it is the heaviest module
    out = []
    dash = bd.settings(root)
    host, proj = bd.targets(dash)
    via = bd.provider(dash)
    field = "vercel_project" if via == "vercel" else "cloudflare_pages_project"
    if not host and not proj:
        out.append(item("hosting", "Dashboard hosting", "info", "built every hour but not served yet; the Claude page "
                        "is the backup", "Set host and cloudflare_pages_project (or provider \"vercel\" and "
                        "vercel_project) in founder/dashboard.json", "The startup dashboard"))
    elif via not in bd.PROVIDERS:
        out.append(item("hosting", "Dashboard hosting", "broken", f"provider {via!r} isn't one of "
                        + ", ".join(bd.PROVIDERS), "Set provider to cloudflare or vercel in founder/dashboard.json",
                        "The startup dashboard"))
    elif not bd.HOST.match(host) or not bd.project_ok(dash):
        out.append(item("hosting", "Dashboard hosting", "broken", f"host or {field} is malformed",
                        "Use a domain like pm.example.com and a " + ("Vercel" if via == "vercel" else "Pages")
                        + " project name", "The startup dashboard"))
    else:
        names = ("VERCEL_TOKEN",) if via == "vercel" else ("CLOUDFLARE_API_TOKEN", "CLOUDFLARE_ACCOUNT_ID")
        flags = {n: has_secret(n, hub, cache) for n in names}
        unset = [n for n, v in flags.items() if v is False]
        unknown = [n for n, v in flags.items() if v is None]
        where = "Vercel" if via == "vercel" else "Cloudflare"
        out.append(item("hosting", "Dashboard hosting",
                        "broken" if unset else "unknown" if unknown else "ok",
                        f"{host} on {where}: " + ("secrets not set: " + ", ".join(unset) if unset else
                                                  "couldn't check the secrets from here" if unknown else "secrets set"),
                        "Add the repository secret" + ("s " if len(names) > 1 else " ") + " and ".join(names)
                        + (" (the deploy also needs Vercel Authentication on All Deployments)" if via == "vercel" else "")
                        if unset or unknown else "", "The startup dashboard"))
    port = load_json(root, "founder/portfolio.json")
    ventures = (port or {}).get("ventures") if isinstance(port, dict) else None
    if ventures:
        tok = has_secret("PORTFOLIO_TOKEN", hub, cache)
        out.append(item("portfolio", "Portfolio", "ok" if tok else "broken" if tok is False else "unknown",
                        f"{len(ventures)} ventures; PORTFOLIO_TOKEN " + ("set" if tok else "not set" if tok is False
                                                                          else "couldn't be checked from here"),
                        "" if tok else "Add PORTFOLIO_TOKEN: read-only Actions access to each venture's repo",
                        "The portfolio"))
    return out


def github_checks(root: Path, hub: tickets.Hub, now: dt.datetime) -> list[dict[str, str]]:
    out = []
    try:
        have = {lb.get("name") for lb in hub.api("labels?per_page=100") or []}
        missing = [n for n in LABELS if n not in have]
        out.append(item("labels", "GitHub labels", "todo" if missing else "ok",
                        "missing: " + ", ".join(missing) if missing else f"{len(LABELS)} labels in place",
                        "doctor --repair creates them", "The AI team", "labels" if missing else ""))
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError, AttributeError):
        out.append(item("labels", "GitHub labels", "unknown", "couldn't read the repo's labels"))

    roles = heartbeat.policy(root).get("roles") or {}
    on = [r for r, v in roles.items() if isinstance(v, dict) and v.get("enabled") and r != "board"
          and (v.get("monthly_budget_usd") or 0) > 0]
    if on:
        try:
            seen: dict[str, str] = {}
            for month in {now.strftime("%Y-%m"), (now - dt.timedelta(hours=NO_RUN_HOURS)).strftime("%Y-%m")}:
                for cm in heartbeat.Costs(hub, month).comments():
                    m = heartbeat.MARK.search(cm.get("body") or "")
                    data = json.loads(m.group(1)) if m else {}
                    role = data.get("role") if isinstance(data, dict) else None
                    if role:
                        seen[role] = max(seen.get(role, ""), str(cm.get("created_at") or ""))
            cutoff = (now - dt.timedelta(hours=NO_RUN_HOURS)).strftime("%Y-%m-%dT%H:%M:%SZ")
            quiet = [r for r in on if seen.get(r, "") < cutoff]
            out.append(item("runs", "Heartbeat runs", "todo" if quiet else "ok",
                            f"no run recorded in {NO_RUN_HOURS}h: " + ", ".join(quiet) if quiet
                            else "every role that is on has run recently",
                            "Create each one's cloud scheduled task (python tools/heartbeat.py plan prints the prompt), "
                            "or turn it off", "The AI team"))
        except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError, AttributeError):
            out.append(item("runs", "Heartbeat runs", "unknown", "couldn't read the cost log"))

    try:
        got = hub.api("actions/workflows/dashboard.yml/runs?per_page=5&branch=main") or {}
        runs = [r for r in got.get("workflow_runs") or [] if r.get("status") == "completed"]
        last = runs[0] if runs else None
        if last is None:
            out.append(item("dashboard_run", "Dashboard build", "info", "no finished run yet"))
        else:
            ok = last.get("conclusion") == "success"
            out.append(item("dashboard_run", "Dashboard build", "ok" if ok else "broken",
                            f"last run {last.get('conclusion')} at {str(last.get('updated_at', ''))[:16]}",
                            "" if ok else f"Open the run and read the failing step: {last.get('html_url', '')}",
                            "The startup dashboard"))
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError, AttributeError):
        out.append(item("dashboard_run", "Dashboard build", "unknown", "couldn't read the workflow runs"))
    return out


def run(root: Path, offline: bool = False, now: dt.datetime | None = None,
        hub: tickets.Hub | None = None) -> list[dict[str, str]]:
    now = now or dt.datetime.now(dt.timezone.utc)
    if hub is None and not offline:
        repo = approval.repo_name(root)
        hub = tickets.Hub(repo) if repo else None
    cache: dict[str, Any] = {}
    found = repo_checks(root) + hosting_checks(root, None if offline else hub, cache)
    if hub is not None and not offline:
        found += github_checks(root, hub, now)
    return sorted(found, key=lambda x: STATUSES.index(x["status"]))


def needs_you(found: list[dict[str, str]]) -> list[dict[str, str]]:
    return [x for x in found if x["status"] in ("broken", "todo")]


def repair(root: Path, found: list[dict[str, str]], hub: tickets.Hub | None) -> list[str]:
    """Fix what is safe to fix. File changes stay in the working tree; the doctor skill opens the PR."""
    done = []
    wanted = {x["repair"] for x in found if x.get("repair")}
    if "goals" in wanted:
        (root / "founder").mkdir(exist_ok=True)
        (root / "founder" / "goals.json").write_text(json.dumps(GOALS_TEMPLATE, indent=2) + "\n", encoding="utf-8",
                                                     newline="\n")
        done.append("wrote an empty founder/goals.json")
    if "gates" in wanted or "goals" in wanted:
        data = load_json(root, "founder/gates.json")
        if isinstance(data, dict):
            changed = []
            for rel, gate in GATED.items():
                g = (data.setdefault("gates", {})).get(gate)
                if isinstance(g, dict) and rel not in g.setdefault("paths", []):
                    g["paths"].append(rel)
                    changed.append(f"{rel} → {gate}")
            if changed:
                (root / "founder" / "gates.json").write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n",
                                                             encoding="utf-8", newline="\n")
                done.append("added to founder/gates.json: " + ", ".join(changed))
    if "labels" in wanted and hub is not None:
        have = {lb.get("name") for lb in hub.api("labels?per_page=100") or []}
        for name, color in LABELS.items():
            if name not in have:
                hub.api("labels", "-X", "POST", payload={"name": name, "color": color})
                done.append(f"created label {name}")
    return done


def report(found: list[dict[str, str]]) -> str:
    marks = {"ok": "ok     ", "todo": "TO DO  ", "broken": "BROKEN ", "info": "info   ", "unknown": "unknown"}
    lines = []
    for x in found:
        lines.append(f"{marks[x['status']]} {x['title']}: {x['detail']}".rstrip(": "))
        if x["fix"] and x["status"] not in ("ok",):
            lines.append(f"        fix: {x['fix']}" + (f" (handbook: {x['section']})" if x["section"] else ""))
    n = len(needs_you(found))
    lines.append(f"\n{n} item{'s' if n != 1 else ''} need{'s' if n == 1 else ''} you." if n else "\nAll set.")
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Is this venture's operating system set up and healthy?")
    ap.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap.add_argument("--offline", action="store_true", help="check the repo only, not GitHub")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--repair", action="store_true", help="fix what is safe to fix")
    a = ap.parse_args(argv)
    found = run(a.root, a.offline)
    if a.repair:
        repo = approval.repo_name(a.root)
        hub = tickets.Hub(repo) if repo and not a.offline else None
        for line in repair(a.root, found, hub):
            print(f"repaired: {line}")
        found = run(a.root, a.offline)
    print(json.dumps(found, indent=1) if a.json else report(found))
    return 1 if any(x["status"] == "broken" for x in found) else 0


if __name__ == "__main__":
    sys.exit(main())
